plain('Admission', 'Admit to the ICU (bed assigned for IV insulin, continuous telemetry and hourly glucose checks): SGLT2-inhibitor-associated DKA with near-normal glucose, sepsis from a probable urinary source, acute metabolic encephalopathy (delirium) and acute kidney injury. Full code. Attending: H. Calloway, MD (days) / S. Abrams, MD (nights)', T('Thu', '07:00'), { provider: WHO.icuD, frequency: 'Once', orderedAt: T('Thu', '01:35') });
plain('Nursing', 'K 3.3 (0650 specimen, released 0700): HOLD the insulin infusion NOW and notify the prescriber. Reduce D10W to 50 mL/h while insulin is held; continue hourly POC glucose. Stop lactated Ringer\'s and run potassium-free 0.9% sodium chloride at 100 mL/h. Four sequential KCl 10 mEq/100 mL riders at 0700, 0800, 0900 and 1000 on a pump, one at a time. Draw a potassium at 0900 (before the third rider starts). No insulin restart until a repeat K is 3.5 or higher and the prescriber has reviewed it', T('Thu', '07:00'), { provider: WHO.icuD, orderedAt: T('Thu', '07:00'), end: T('Thu', '09:15'), stoppedEarly: true, instructions: 'Independent check of the new pump settings. Do not accelerate the potassium. Inspect the peripheral site and ask about pain every hour. Persistent DKA (BHB 4.1) despite the low glucose: the hold is for potassium safety, and it is as short as possible.' });
med({ key: 'kcl_unit_4', name: 'potassium chloride 10 mEq in 100 mL premixed piggyback (unit riders 1-4)', dose: '10 mEq over 1 hour (100 mL/h)', route: 'IV', frequency: 'Four sequential riders, 0700, 0800, 0900 and 1000, one at a time on a pump; 10 mEq/h maximum from all sources', kind: 'sched', start: T('Thu', '07:00'), end: T('Thu', '11:00'), provider: WHO.icuD, orderedAt: T('Thu', '07:00'), drugClass: 'Electrolyte replacement', highAlert: true, dispense: 'ICU automated dispensing cabinet (premixed bags)', rationale: 'K 3.3 despite 20 mEq in the ED, on insulin: replace before and during insulin. Urine output is adequate (700 mL in the ED). Potassium-free saline is the carrier; D10W and insulin contain no potassium; combined delivery stays at exactly 10 mEq/h.',
  instructions: 'Peripheral IV C (left antecubital 18 g), pump, ONE bag at a time, never in parallel, never IV push. Recheck K at 0900 (after two riders, before the third starts) and at completion. Stop and call for pain, redness or swelling, urine under 30 mL/h, an arrhythmia or a new ECG change.', due: [T('Thu', '07:00'), T('Thu', '08:00'), T('Thu', '09:00'), T('Thu', '10:00')], monitor: [KMON] });
med({ key: 'ns_100_unit', name: '0.9% sodium chloride (potassium-free), 1,000 mL bag, carrier during the unit potassium riders', dose: '100 mL/h', route: 'IV', frequency: 'Continuous 0700-1100 during four riders', kind: 'cont', start: T('Thu', '07:00'), end: T('Thu', '11:00'), stoppedEarly: true, stopLabel: 'riders finished, perfusion and urine improved: D10W alone', provider: WHO.icuD, orderedAt: T('Thu', '07:00'), drugClass: 'Isotonic crystalloid', concentration: 'NS 1,000 mL bag', dispense: 'Central Pharmacy (IV room)',
  rationale: 'Replaces lactated Ringer\'s (potassium 4 mEq/L) so riders never exceed the 10 mEq/h limit. 400 mL over 4 hours.', instructions: '100 mL/h by pump through IV B. Stop at 1100 when the fourth rider finishes (perfusion and urine improved, and D10W provides substantial ongoing volume). Reassess lungs and urine every 2 hours.', due: [T('Thu', '07:00')], dueDoses: ['Start 100 mL/h; stop lactated Ringer\'s'], monitor: [POC] });
plain('Nursing', 'Continuous telemetry. Neurologic and attention assessment every 2 hours initially, with CAM-ICU each shift while in the ICU and with any change. Hourly urine by collection hat or commode (assisted, measured voids); no Foley for convenience. Strict I&O and daily weight. NOTIFY for urine under 30 mL/h for 2 hours, new crackles or oxygen need, new focal signs, inability to protect the airway, abrupt mental change, an arrhythmia, glucose under 150 with ketones, or any infusion-site injury', T('Thu', '07:00'), { provider: WHO.icuD, orderedAt: T('Thu', '07:00'), end: T('Fri', '07:00'), instructions: 'From Day 2 0700: mentation each shift and with change, total urine each shift. Peaked T = high K; flat T with U waves = low K, but a normal tracing does not exclude a dangerous level.' });
plain('Nursing', 'Delirium and fall precautions: nurse-assisted mobility and toileting only (bed low with the alarm on, call light within reach, non-slip footwear, tubing cleared and IV sites secured, hourly rounding, no unassisted bathroom trips); reorient at every contact with a clock and calendar, glasses and hearing aids, daytime light, nighttime sleep protection and family presence; AVOID benzodiazepines, routine sedatives and restraints. CAM-ICU in the ICU, CAM on the ward. Escalate new focal signs or abrupt change', T('Thu', '07:00'), { provider: WHO.icuD, orderedAt: T('Thu', '07:00'), end: T('Sun', '07:00'), instructions: 'An alarm never replaces hands-on assistance. Look for treatable causes of worsening attention (glucose, oxygenation, pain, urinary retention, infection, medicines) before labelling it dementia.' });
plain('Consults', 'Endocrinology consultation today (SGLT2-inhibitor-associated DKA, transition planning, hypoglycemia unawareness; follows through discharge for insulin reassessment). Ward: diabetes educator, physical therapy, case management and infectious disease as ordered below', T('Thu', '07:15'), { provider: WHO.icuD, orderedAt: T('Thu', '07:15'), frequency: 'Once', end: T('Sun', '07:00') });
med({ key: 'glucose_po_hypo', name: 'glucose 15 g rapid carbohydrate by mouth (juice 120 mL) - hypoglycemia protocol, nurse-driven', dose: '15 g (120 mL juice)', route: 'Oral', frequency: 'As needed for glucose under 70 when awake and able to swallow; recheck in 15 minutes and repeat until 70 or higher', kind: 'prn', prn: true, start: T('Thu', '02:00'), provider: WHO.icuD, orderedAt: T('Thu', '01:35'), end: T('Sun', '07:00'), drugClass: 'Carbohydrate', rationale: 'Insulin therapy with impaired hypoglycemia awareness.', instructions: 'Rule of 15: 15 g fast carbohydrate, recheck in 15 minutes and repeat until 70 or higher; then a snack if the next meal is more than 1 hour away, with repeat checks individualized. Count the volume on the I&O. Hold rapid-acting insulin and notify the prescriber; review insulin, food and activity for every episode.' });
med({ key: 'd10_hypo', name: 'dextrose 10% injection (hypoglycemia protocol)', dose: '150 mL (15 g) over 15 minutes', route: 'IV', frequency: 'As needed for glucose under 70 when unable to swallow safely and an IV is in place; recheck every 15 minutes; notify the provider', kind: 'prn', prn: true, start: T('Thu', '02:00'), provider: WHO.icuD, orderedAt: T('Thu', '01:35'), end: T('Sun', '07:00'), drugClass: 'Carbohydrate', rationale: 'Insulin therapy; unsafe swallow.', instructions: 'Give through a running peripheral line, never into the insulin line. Count the volume on the I&O.' });
med({ key: 'glucagon_hypo', name: 'glucagon injection (hypoglycemia protocol)', dose: '1 mg', route: 'Intramuscular', frequency: 'As needed once for glucose under 70 when unable to swallow and there is no IV access; summon urgent help', kind: 'prn', prn: true, start: T('Thu', '02:00'), provider: WHO.icuD, orderedAt: T('Thu', '01:35'), end: T('Sun', '07:00'), drugClass: 'Antihypoglycemic', rationale: 'Insulin therapy; no IV access.', instructions: 'Turn her on her side (vomiting is common after glucagon). Call for urgent help while IV access is obtained.' });
plain('Diet', 'NPO except essential medicines and supervised mouth care while nauseated and confused; aspiration assessment before any oral intake', T('Thu', '01:00'), { provider: WHO.ed, orderedAt: T('Thu', '01:00'), end: T('Thu', '11:00'), stoppedEarly: true });
plain('Diet', 'Small supervised clear liquids (water and sugar-free fluids) from 1100; stop if she vomits or the swallow looks unsafe. Her carbohydrate comes principally from the D10W during DKA therapy. Count every oral volume on the I&O', T('Thu', '11:00'), { provider: WHO.icuD, orderedAt: T('Thu', '10:50'), end: T('Fri', '01:00'), stoppedEarly: true });
plain('Lab / Bedside Testing', 'Potassium alone at 0900 (results about 0910); full chemistry, venous gas, BHB, magnesium and phosphorus at 1100, 1450, 1850 and 2250 and at 0650 on Day 2 (CBC with the Day 2 0650 panel). More frequent potassium or gas checks for any deterioration. Serial lactate is finished (last value 1.6)', T('Thu', '07:00'), { provider: WHO.icuD, orderedAt: T('Thu', '07:00'), end: T('Fri', '07:00'), frequency: 'As listed', instructions: 'Draw from an arm without an infusion; potassium samples by separate venipuncture away from the infusing lines.' });
plain('Nursing', 'K 3.7 (0900 specimen): the prescriber has reviewed it. RESTART the regular insulin infusion at 6 units/h (0.1 unit/kg/h) at 0915 and return D10W to 100 mL/h. Keep the last two potassium riders (0900 and 1000) running one at a time; the 0900 rider starts after the sample is drawn. Independent two-nurse check of the insulin rate. Continue hourly POC glucose', T('Thu', '09:15'), { provider: WHO.icuD, orderedAt: T('Thu', '09:15'), end: T('Thu', '13:00'), stoppedEarly: true, instructions: 'Restart needs K 3.5 or higher AND prescriber confirmation (both met). Keep the sodium-chloride carrier until the fourth rider ends.' });
plain('Nursing', 'POC glucose 148 at 1300: increase D10W from 100 to 150 mL/h (15 g/h) under the protocol and notify the prescriber; keep the insulin at 6 units/h because the latest BHB still shows active DKA. POC again in 1 hour (sooner for symptoms). Monitor for volume intolerance (lungs, urine, edema)', T('Thu', '13:00'), { provider: WHO.icuD, orderedAt: T('Thu', '13:00'), end: T('Fri', '01:00'), stoppedEarly: true, instructions: 'No true hypoglycemia yet; her impaired awareness means a symptom-free reading still counts. Two-nurse check of the pump settings.' });
plain('Cardiology', 'ECG 12-lead now for low potassium (K 3.3, magnesium 1.6); acquire 0705, interpretation released 0715', T('Thu', '07:05'), { provider: WHO.icuD, orderedAt: T('Thu', '07:00'), frequency: 'Once', end: T('Thu', '07:15') });
plain('Cardiology', 'Repeat ECG 12-lead after the potassium replacement (potassium 4.0 at 1100); acquire 1115, interpretation released 1125', T('Thu', '11:15'), { provider: WHO.icuD, orderedAt: T('Thu', '11:10'), frequency: 'Once', end: T('Thu', '11:25') });
med({ key: 'magnesium', name: 'magnesium sulfate 2 g in 50 mL premixed bag', dose: '2 g over 1 hour', route: 'IV', frequency: 'Once, 1130-1230, on IV C after the potassium riders finish', kind: 'sched', start: T('Thu', '11:30'), end: T('Thu', '12:30'), provider: WHO.icuD, orderedAt: T('Thu', '11:10'), drugClass: 'Electrolyte replacement', highAlert: true, dispense: 'ICU automated dispensing cabinet (premixed bags)', rationale: 'Magnesium 1.6 at 0650 and again at 1100 with potassium that was hard to correct; kidney function is recovering (creatinine 0.9) so a standard 2 g dose is safe. Repeat magnesium with the 1450 panel.', instructions: 'Pump, 1 hour, peripheral IV C. Watch for flushing, hypotension and a loss of reflexes. The 50 mL counts as IV med on the I&O.', due: [T('Thu', '11:30')], monitor: [mon('Magnesium', 'lab', 'Magnesium')] });
plain('Nursing', 'Phosphorus 1.8 (1100): monitor, do not replace (no respiratory muscle weakness, heart or neurologic problem); replace only for a value under 1.0 or with those signs, using a separate peripheral-rate order. Acetaminophen is the only antipyretic (no NSAIDs while the kidneys recover)', T('Thu', '11:10'), { provider: WHO.icuD, orderedAt: T('Thu', '11:10'), end: T('Fri', '07:00'), instructions: 'Total acetaminophen from all routes must stay at or under 3,000 mg in 24 hours.' });
med({ key: 'acetaminophen_po', name: 'acetaminophen (TYLENOL) tablet, as needed', dose: '650 mg', route: 'Oral', frequency: 'Every 6 hours as needed for pain or fever; maximum 3,000 mg per 24 hours from all routes', kind: 'prn', prn: true, start: T('Thu', '11:00'), provider: WHO.icuD, orderedAt: T('Thu', '10:50'), end: T('Sun', '07:00'), drugClass: 'Analgesic / antipyretic', rationale: 'Pain or fever once she can swallow safely (swallow screened before oral intake). The 0150 rectal dose counts toward the daily maximum.', instructions: 'Complete the aspiration screen first. Document the reason and the response. Not for a headache that comes with new neurologic change: call the prescriber.' });
med({ key: 'kcl_d1_pm', name: 'potassium chloride 10 mEq in 100 mL premixed piggyback (afternoon riders 1 and 2)', dose: '10 mEq over 1 hour (100 mL/h)', route: 'IV', frequency: 'Two sequential riders, 1500 and 1600, one at a time on a pump; 10 mEq/h maximum from all sources', kind: 'sched', start: T('Thu', '15:00'), end: T('Thu', '17:00'), provider: WHO.icuD, orderedAt: T('Thu', '15:00'), drugClass: 'Electrolyte replacement', highAlert: true, dispense: 'ICU automated dispensing cabinet (premixed bags)', rationale: 'K 3.8 at 1450 and still falling (4.0 to 3.8) on insulin with ketones present: two further riders. D10W and insulin contain no potassium; recheck on the 1850 panel.', instructions: 'Peripheral IV C, pump, ONE bag at a time, never IV push. Urine at least 30 mL/h. Check the site hourly.', due: [T('Thu', '15:00'), T('Thu', '16:00')], monitor: [KMON] });
plain('Consults', 'Dietitian consultation: carbohydrate intake and illness nutrition; a short first visit while she is on supervised clear liquids, full teaching when her attention improves', T('Thu', '18:30'), { provider: WHO.icuD, orderedAt: T('Thu', '15:00'), frequency: 'Once', end: T('Fri', '13:00') });
// ---- transition (written 2250-2315 with the resolution labs)
med({ key: 'glargine_12', name: 'insulin glargine (LANTUS) pen U-100 (first inpatient basal dose)', dose: '12 units', route: 'Subcutaneous', frequency: 'Every 24 hours at 2300 (first dose now, 2 hours before the infusion stops)', kind: 'sched', start: T('Thu', '23:00'), end: T('Sat', '21:45'), stoppedEarly: true, stopLabel: 'dose reduced to 10 units (glucose 63)', provider: WHO.icuN, orderedAt: T('Thu', '23:00'), drugClass: 'Long-acting (basal) insulin', highAlert: true, dispense: 'Pharmacy: patient-specific pen',
  rationale: 'DKA resolved on the 2250 specimen (BHB 0.4, venous pH 7.36, bicarbonate 19, gap 10). Basal insulin goes in 2 hours BEFORE the infusion stops. 12 units (0.2 unit/kg; estimated total daily dose about 0.35 unit/kg = 21 units, basal 12 plus meals about 9) is below her home 18 units: older adult, recent AKI, reduced intake and impaired hypoglycemia awareness. Do not derive the home total from the high infusion rate.', instructions: 'Give at 2300 with the IV insulin and D10W still running; both stop at 0100 only after the dose is verified, she is drinking and eating, and she has not vomited again. Do NOT also give a home 2100 dose. Basal insulin is never permanently omitted in type 1 diabetes.', info: 'Without a long-acting depot, stopping the infusion means the ketones return within hours.', due: [T('Thu', '23:00'), T('Fri', '23:00')], dueDoses: ['12 units (2 hours before the infusion stops)', '12 units'], monitor: [POC] });
plain('Nursing', 'Resolution confirmed on the 2250 panel. Give glargine at 2300 and continue the IV insulin and D10W until 0100 (a full 2-hour overlap). Stop BOTH at 0100 only after: the glargine dose is verified, she can drink and eat, and she has not vomited again. Record the glucose and the overlap. Disconnect the insulin tubing and clear the residual drug before saline-locking. Extra POC glucose at 0200', T('Thu', '23:00'), { provider: WHO.icuN, orderedAt: T('Thu', '23:00'), frequency: 'Once', end: T('Fri', '01:00'), instructions: 'Do not stop the infusion before the glargine has had its 2 hours.' });
plain('Diet', 'Consistent-carbohydrate diet, about 45 g carbohydrate per meal (smaller portions allowed and counted by the nurse or dietitian). Oral fluids as tolerated; no routine maintenance IV fluid after the D10W stops. Avoid uncounted large carbohydrate drinks except to treat hypoglycemia', T('Fri', '01:00'), { provider: WHO.icuN, orderedAt: T('Thu', '23:05'), end: T('Sun', '07:00') });
med({ key: 'lispro_meal_1', name: 'insulin lispro (HUMALOG) pen U-100 - AFTER-MEAL dose (carbohydrate eaten + premeal correction)', dose: '1 unit per 15 g carbohydrate actually eaten (nearest whole unit) PLUS correction from the premeal POC glucose: under 200: none; 200-249: +1; 250-299: +2; 300-349: +3; 350 or higher: +4 and call the prescriber', route: 'Subcutaneous', frequency: 'After meals, within 15 minutes of finishing; no bedtime correction', kind: 'sched', start: T('Fri', '08:00'), end: T('Sat', '21:45'), stoppedEarly: true, stopLabel: 'ratio changed to 1 unit per 18 g', provider: WHO.icuN, orderedAt: T('Thu', '23:05'), drugClass: 'Rapid-acting (bolus) insulin', highAlert: true, dispense: 'Pharmacy: patient-specific pen',
  rationale: 'Cautious dosing by what she actually eats (appetite is unreliable after delirium and illness). Hold the carbohydrate dose if the meal is not eaten; never automatically hold the basal. Notify for a premeal glucose under 100 or repeated values over 250.', instructions: 'Use the premeal POC for the correction and the eaten carbohydrate for the meal dose; add them in one injection. Normal meal: 45 g = 3 units; a premeal of 204 adds 1 unit. No bedtime correction. Verify with a second nurse.', due: [T('Fri', '08:00'), T('Fri', '12:00'), T('Fri', '18:00'), T('Sat', '08:00'), T('Sat', '12:00'), T('Sat', '18:00')], dueDoses: Array(6).fill('1 unit per 15 g carbohydrate eaten + premeal correction'), monitor: [POC] });
plain('Lab / Bedside Testing', 'POC glucose one hour after the infusion stops (0200), then before meals and at bedtime (0730, 1130, 1730, 2100), with extra 15-minute checks for any hypoglycemia and a targeted check after any dose change. Chemistry on Day 2 at 1850, Day 3 at 0650 and 1850 and Day 4 at 0650; CBC, magnesium and phosphorus with the Day 3 and Day 4 0650 panels. BHB and a gas only for recurrent symptoms, a falling bicarbonate or an unexplained glucose change. Vomiting, abdominal pain, deep breathing, confusion or glucose over 250 twice means an immediate prescriber review', T('Thu', '23:00'), { provider: WHO.icuN, orderedAt: T('Thu', '23:00'), end: T('Sun', '07:00'), frequency: 'As listed', instructions: 'Treat glucose under 70 with the hypoglycemia order. Do not repeat a correction within 4 hours.' });
plain('Nursing', 'EMPAGLIFLOZIN: discontinue permanently (SGLT2-inhibitor-associated DKA in type 1 diabetes, an off-label use). Document a serious adverse drug reaction; medication reconciliation must not reactivate it, and no SGLT2 inhibitor is to be rechallenged. HOLD home lisinopril for the whole admission (dehydration and AKI); the outpatient clinician reassesses before restarting', T('Thu', '01:35'), { provider: WHO.ed, orderedAt: T('Thu', '01:35'), end: T('Sun', '07:00'), instructions: 'Home medicines: glargine and lispro (replaced by the orders here), atorvastatin 20 mg (held while acutely ill), glucagon nasal powder 3 mg as needed (home), empagliflozin (stopped), lisinopril (held).' });
med({ key: 'enoxaparin', name: 'enoxaparin (LOVENOX) injection - VTE prophylaxis', dose: '40 mg', route: 'Subcutaneous', frequency: 'Once daily at 0900 while hospitalized', kind: 'sched', start: T('Thu', '09:00'), end: T('Sun', '07:00'), provider: WHO.icuD, orderedAt: T('Thu', '07:15'), drugClass: 'Anticoagulant (low-molecular-weight heparin)', highAlert: true, dispense: 'ICU automated dispensing cabinet',
  rationale: 'DOCUMENTED CLOT-RISK FACTORS: age 67, sepsis (acute infection), ICU stay with reduced mobility (nurse-assisted mobility only, delirium; confined to bed for much of the first days), risk-model score 4 (reduced mobility 3 + acute infection 1 = high risk). No active bleeding, platelets 240, estimated creatinine clearance 43 mL/min or higher (no dose change needed at 60 kg). Inpatient only; no home continuation.', instructions: 'Give in the abdomen away from the umbilicus, rotate sites, do not rub. Check for bleeding or bruising and review the platelet count with each CBC. Hold and call for bleeding, platelets under 100 or a fall of more than 50 percent, or a creatinine clearance under 30 mL/min. Ends at actual discharge.', due: [T('Thu', '09:00'), T('Fri', '09:00'), T('Sat', '09:00')], monitor: [mon('Platelets', 'lab', 'Platelets')] });
plain('Consults', 'Infectious disease consultation after the E. coli identification: review the final susceptibilities when released and plan narrow oral treatment (allergy: sulfonamide antibiotics). Pharmacy medication reconciliation and antibiotic dose and route verification, with a permanent SGLT2-inhibitor flag. Case management (daughter supervision, cat care, supplies, affordability, home nursing, follow-up). Physical therapy (gait, assistive device, entrance steps). Diabetes educator (ketone testing, CGM reconnection and alerts, pen demonstration, hypoglycemia rescue, daughter teach-back)', T('Fri', '09:00'), { provider: WHO.icuD, orderedAt: T('Fri', '08:30'), frequency: 'Once', end: T('Sun', '07:00'), instructions: 'Infectious disease at 1100, pharmacy at 1200, case management at 1500 on Day 2; physical therapy at 0930 and the educator at 1100 on Day 3.' });
plain('Nursing', 'Assisted ambulation with a walker pending the physical therapy evaluation; chair for meals; one-person hands-on assistance and scheduled toileting. Do not replace assessment with alarms alone', T('Fri', '09:00'), { provider: WHO.icuD, orderedAt: T('Fri', '08:30'), end: T('Sun', '07:00'), instructions: 'She tends to stand before asking for help: offer toileting on a schedule (every 2 hours while awake).' });
med({ key: 'amoxicillin', name: 'amoxicillin capsule (narrowed oral antibiotic)', dose: '1,000 mg', route: 'Oral', frequency: 'Every 8 hours at 0600, 1400 and 2200; first dose 1400 on Day 2; last dose 2200 on 11/11 (day 7)', kind: 'sched', start: T('Fri', '14:00'), end: T('Sun', '07:00'), provider: WHO.id, orderedAt: T('Fri', '11:00'), drugClass: 'Aminopenicillin antibiotic', dispense: 'Pharmacy to load in ADS',
  rationale: 'E. coli (final urine culture) susceptible to ampicillin (MIC 2) and amoxicillin-clavulanate; she is improving, tolerating oral intake, kidney function has recovered (estimated clearance about 65 mL/min), and the ultrasound showed no obstruction. NO penicillin allergy. The report also lists trimethoprim-sulfamethoxazole as susceptible, but it is CONTRAINDICATED for her (sulfonamide antibiotic allergy, urticaria); ciprofloxacin is resistant. Seven calendar treatment days including the IV therapy.', instructions: 'Verify the allergy list at every dose (sulfonamide antibiotics only). Give with water; swallow screen as ordered. Doses after this admission continue at home through 11/11 at 2200 (11 doses remain after Day 4 0700). Reassess the duration for relapse, obstruction or slow improvement.', due: [T('Fri', '14:00'), T('Fri', '22:00'), T('Sat', '06:00'), T('Sat', '14:00'), T('Sat', '22:00'), T('Sun', '06:00')], monitor: [mon('Urine culture', 'lab', 'Urine culture')] });
med({ key: 'atorvastatin', name: 'atorvastatin (LIPITOR) tablet (home medicine, resumed)', dose: '20 mg', route: 'Oral', frequency: 'Daily at 2100 from Day 2 (no Day 1 dose and no catch-up dose)', kind: 'sched', start: T('Fri', '21:00'), end: T('Sun', '07:00'), provider: WHO.icuD, orderedAt: T('Fri', '07:00'), drugClass: 'Statin', rationale: 'Home hyperlipidemia treatment; held on Day 1 for acute illness and limited intake.', instructions: 'Give with water once she is eating her diet.', due: [T('Fri', '21:00'), T('Sat', '21:00')] });
plain('Nursing', 'After the assisted near-fall (2015): examine for injury and check cognition; immediate POC glucose done; the prescriber has been notified. Reassess the toileting plan: hands-on assistance for every transfer and scheduled toileting. No imaging is indicated without a fall to the floor, head strike or any injury sign. Recheck neurologic status and glucose at 2100', T('Fri', '20:30'), { provider: WHO.icuN, orderedAt: T('Fri', '20:30'), end: T('Sun', '07:00'), instructions: 'Document the event. Repeat the check in the morning for delayed pain.' });
plain('Transfer', 'Transfer from the ICU to a medical ward bed at 1000 after sustained resolution and improved attention. Continue fall precautions, delirium measures and AC/HS glucose; no further invasive monitoring', T('Sat', '10:00'), { provider: WHO.icuD, orderedAt: T('Sat', '07:15'), frequency: 'Once', end: T('Sun', '07:00') });
plain('Nursing', 'Hypoglycemia, POC 63: give 120 mL juice (15 g carbohydrate) now under the hypoglycemia order and recheck at 2115. The prescriber is notified now. No bedtime correction insulin. Stay with her and check for symptoms she may not feel (impaired awareness)', T('Sat', '21:05'), { provider: WHO.wardN, orderedAt: T('Sat', '21:05'), end: T('Sat', '21:15'), stoppedEarly: true, instructions: 'Hold any meal-dose insulin; report the recheck result to the prescriber.' });
plain('Nursing', 'POC 88 at 2115: give a 15 g carbohydrate cracker snack (the next meal is not soon); recheck at 2130 and 2200 and communicate the recovery to the prescriber', T('Sat', '21:15'), { provider: WHO.wardN, orderedAt: T('Sat', '21:15'), end: T('Sat', '22:00'), stoppedEarly: true });
plain('Consults', 'Endocrinology reassessment after the treated low glucose: telephone insulin-dose advice now, formal note to follow', T('Sat', '21:30'), { provider: WHO.wardN, orderedAt: T('Sat', '21:30'), frequency: 'Once', end: T('Sat', '21:50') });
med({ key: 'glargine_10', name: 'insulin glargine (LANTUS) pen U-100 (revised dose)', dose: '10 units', route: 'Subcutaneous', frequency: 'Every 24 hours at 2300 (first dose Day 3)', kind: 'sched', start: T('Sat', '23:00'), end: T('Sun', '07:00'), provider: WHO.endo, orderedAt: T('Sat', '21:45'), drugClass: 'Long-acting (basal) insulin', highAlert: true, dispense: 'Pharmacy: patient-specific pen',
  rationale: 'Asymptomatic glucose of 63 on Day 3 with improving insulin sensitivity, more activity, variable appetite and impaired hypoglycemia awareness. 10 units is 0.17 unit/kg. Basal insulin is still given (type 1 diabetes); she is monitored closely rather than omitted.', instructions: 'Give at 2300 after the glucose has recovered (checked at 2200). Do NOT give 12 units. Targeted POC at 0300.', due: [T('Sat', '23:00')], dueDoses: ['10 units (revised from 12)'], monitor: [POC] });
med({ key: 'lispro_meal_2', name: 'insulin lispro (HUMALOG) pen U-100 - AFTER-MEAL dose (revised ratio)', dose: '1 unit per 18 g carbohydrate actually eaten (nearest whole unit) PLUS the same premeal correction (under 200: none; 200-249: +1; 250-299: +2; 300-349: +3; 350 or higher: +4 and call the prescriber)', route: 'Subcutaneous', frequency: 'After meals, within 15 minutes of finishing; no bedtime correction (first use at breakfast on Day 4)', kind: 'sched', start: T('Sat', '21:45'), provider: WHO.endo, orderedAt: T('Sat', '21:45'), drugClass: 'Rapid-acting (bolus) insulin', highAlert: true, dispense: 'Pharmacy: patient-specific pen',
  rationale: 'Ratio loosened after the asymptomatic low. Notify for a premeal glucose under 100 or repeated values over 250.', instructions: 'Eaten carbohydrate divided by 18, rounded to the nearest whole unit, plus the correction in one injection. Verify with a second nurse.' });
plain('Discharge', 'Conditional home discharge planned for about 1000 on Day 4 after: breakfast tolerance, supplies checked, daughter escort, repeat teach-back of the revised insulin regimen and no recurrent low. Home regimen: glargine 10 units at 2300 daily; lispro after meals 1 unit per 18 g carbohydrate eaten plus the premeal correction (no bedtime correction); amoxicillin 1,000 mg three times daily through 11/11 at 2200; atorvastatin 20 mg at 2100; nasal glucagon 3 mg as needed (may repeat after 15 minutes with a new device while emergency help is called). EMPAGLIFLOZIN STOPPED PERMANENTLY; lisinopril stays on hold until the outpatient clinician restarts it. Enoxaparin and the inpatient rescue orders end at discharge', T('Sun', '07:00'), { provider: WHO.wardD, orderedAt: T('Sun', '06:50'), frequency: 'Once', end: T('Sun', '07:00'), instructions: 'Not yet carried out. If glucose falls again, intake is poor, confusion returns or supervision cannot be arranged, reassess instead of discharging. The five-day blood-culture result is still pending: the inpatient team owns the follow-up.' });

// ---------------- devices
const dev = (deviceType, type, location, siteMarker, placed, o = {}) => ({ id: `device_${slug(type)}_${slug(location)}_${slug(placed)}`, deviceType, type, location, siteMarker, placementDate: placed, status: o.status || 'Patent', lastAssessment: `${o.assessedAt || placed} - ${o.assess || 'site clean, dry, intact'}`, ...(o.gauge ? { gauge: o.gauge } : {}), ...(o.infusing ? { infusing: o.infusing } : {}), ...(o.removedAt ? { removedAt: o.removedAt, removedNote: o.removedNote || '' } : {}) });
