  dev('IV', 'Peripheral IV A', 'Right forearm', 'rightForearm', T('Thu', '01:30'), { gauge: '20 gauge', status: 'Infusing', infusing: 'Regular insulin infusion on its own dedicated pump and line', assess: 'placed in the ED, clean, dry, intact, no redness or swelling', assessedAt: T('Thu', '06:55'), removedAt: T('Fri', '03:00'), removedNote: 'Removed intact after the insulin tubing was cleared and the post-transition glucose was checked' }),
  dev('IV', 'Peripheral IV B', 'Left forearm', 'leftForearm', T('Thu', '01:45'), { gauge: '20 gauge', status: 'Infusing', infusing: 'Lactated Ringer\'s or potassium-free saline and D10W on separately controlled pumps (manifold)', assess: 'placed in the ED, flushes easily, blood return present', assessedAt: T('Thu', '06:55'), removedAt: T('Fri', '03:00'), removedNote: 'Removed intact after the D10W stopped' }),
  dev('IV', 'Peripheral IV C', 'Left antecubital', 'leftAC', T('Thu', '02:00'), { gauge: '18 gauge', status: 'Infusing', infusing: 'Potassium chloride and magnesium piggybacks, ceftriaxone, flushes; later the saline lock (kept for hypoglycemia rescue access)', assess: 'placed in the ED, patent, no pain with potassium', assessedAt: T('Thu', '06:55') }),
  dev('Tube', 'Cardiac monitor (telemetry, 5-lead) and pulse oximeter', 'Chest', 'chestLeft', T('Thu', '01:00'), { status: 'Monitoring', assess: 'leads on, sinus tachycardia, alarms on' })
